213	    private Xzj27 createAndSaveOrderBid(Xrd81 user, Xdh20 productSize, int bidPrice, Xdg64 order) {
214	        Xzj27 orderBid = Xzj27.builder()
215	                .user(user)
216	                .productSize(productSize)
217	                .bidPrice(bidPrice)
218	                .status(Xtz73Status.PENDING)
219	                .order(order)
220	                .build();
221	
222	
223	        orderBid.assignOrder(order);
224	
225	        return orderBidRepository.save(orderBid);
226	    }
