309	        Instant start = Instant.now();
310	        String url = BASE_URL + CANCEL_PAYMENT_URL;
311	
312	        log.info("PortOne API 결제 환불 요청 시작: impUid={}", impUid);
313	
314	        if (impUid == null || impUid.isBlank()) {
315	            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED, "환불할 결제 ID가 없습니다.");
316	        }
317	
318	        String accessToken;
319	        try {
320	            accessToken = getAccessToken();
321	        } catch (Xbf54Exception e) {
322	            log.error("결제 환불 요청 중 토큰 발급 실패: {}", e.getMessage());
323	            throw e;
324	        }
325	
326	        Map<String, String> requestBody = new HashMap<>();
327	        requestBody.put("imp_uid", impUid);
328	        requestBody.put("reason", "사용자 요청에 의한 환불");
329	
330	        HttpHeaders headers = new HttpHeaders();
331	        headers.set("Authorization", "Bearer " + accessToken);
332	        headers.setContentType(MediaType.APPLICATION_JSON);
333	
334	        try {
335	            ObjectMapper objectMapper = new ObjectMapper();
336	            String jsonBody = objectMapper.writeValueAsString(requestBody);
337	
338	            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);
339	            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);
340	
341	            log.debug("PortOne API 결제 환불 응답: 상태코드={}", response.getStatusCodeValue());
342	
343	            boolean success = response.getStatusCode() == HttpStatus.OK && response.getBody().get("code").equals(0);
344	            if (success) {
345	                log.info("PortOne API 결제 환불 성공: impUid={}", impUid);
346	            } else {
347	                String errorMessage = "결제 환불 요청 실패: " +
348	                        (response.getBody().containsKey("message") ? response.getBody().get("message") : "알 수 없는 오류");
349	                log.error("PortOne API 결제 환불 요청 실패: {}", errorMessage);
350	            }
351	
352	
353	            Instant end = Instant.now();
354	            Duration duration = Duration.between(start, end);
355	            log.debug("PortOne API 결제 환불 처리 시간: {}ms", duration.toMillis());
356	
357	            return success;
358	        } catch (Xbf54Exception e) {
359	            throw e;
360	        } catch (RestClientException e) {
361	            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
362	            throw new Xbf54ApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
363	        } catch (Exception e) {
364	            log.error("PortOne API 결제 환불 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
365	            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED, "결제 환불 처리 중 오류가 발생했습니다.", e);
